"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

from dataclasses import dataclass

_IDENTIFIER_CHARS = frozenset(
    "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-"
)
_DIGITS = frozenset("0123456789")

_OPERATORS = ("<=", ">=", "^", "~", "<", ">", "=")
_OPERATOR_SET = frozenset(_OPERATORS)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


@dataclass(frozen=True)
class _Comparator:
    operator: str
    version: Version


def _is_identifier(text: str) -> bool:
    return bool(text) and all(char in _IDENTIFIER_CHARS for char in text)


def _is_numeric_identifier(text: str) -> bool:
    return bool(text) and all(char in _DIGITS for char in text)


def _is_numeric_part(text: str) -> bool:
    return _is_numeric_identifier(text) and (len(text) == 1 or text[0] != "0")


def _parse_identifiers(
    raw: str, original: str, *, allow_leading_zeros: bool
) -> tuple[str, ...]:
    identifiers = raw.split(".")
    for identifier in identifiers:
        if not _is_identifier(identifier):
            raise ValueError(f"invalid version: {original!r}")
        if (
            not allow_leading_zeros
            and _is_numeric_identifier(identifier)
            and len(identifier) > 1
            and identifier[0] == "0"
        ):
            raise ValueError(f"invalid version: {original!r}")
    return tuple(identifiers)


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise TypeError("version must be a string")

    main, plus, build_text = text.partition("+")
    if plus:
        if "+" in build_text:
            raise ValueError(f"invalid version: {text!r}")
        build = _parse_identifiers(build_text, text, allow_leading_zeros=True)
    else:
        build = ()

    core_text, dash, prerelease_text = main.partition("-")
    if dash:
        prerelease = _parse_identifiers(
            prerelease_text, text, allow_leading_zeros=False
        )
    else:
        prerelease = ()

    parts = core_text.split(".")
    if len(parts) != 3 or not all(_is_numeric_part(part) for part in parts):
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch = (int(part) for part in parts)

    return Version(major, minor, patch, prerelease, build)


def _coerce_version(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    if isinstance(value, str):
        return parse(value)
    raise TypeError("version must be a str or Version")


def _compare_prerelease(
    a: tuple[str, ...], b: tuple[str, ...]
) -> int:
    for left, right in zip(a, b):
        if left == right:
            continue
        left_numeric = _is_numeric_identifier(left)
        right_numeric = _is_numeric_identifier(right)
        if left_numeric and right_numeric:
            left_number = int(left)
            right_number = int(right)
            if left_number != right_number:
                return -1 if left_number < right_number else 1
        elif left_numeric:
            return -1
        elif right_numeric:
            return 1
        else:
            return -1 if left < right else 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left = _coerce_version(a)
    right = _coerce_version(b)

    for left_part, right_part in (
        (left.major, right.major),
        (left.minor, right.minor),
        (left.patch, right.patch),
    ):
        if left_part != right_part:
            return -1 if left_part < right_part else 1

    if not left.prerelease and not right.prerelease:
        return 0
    if not left.prerelease:
        return 1
    if not right.prerelease:
        return -1
    return _compare_prerelease(left.prerelease, right.prerelease)


def _same_release(a: Version, b: Version) -> bool:
    return (a.major, a.minor, a.patch) == (b.major, b.minor, b.patch)


def _parse_comparator(token: str, version_text: str, original: str) -> _Comparator:
    try:
        version = parse(version_text)
    except ValueError:
        raise ValueError(f"invalid range: {original!r}") from None
    return _Comparator(token, version)


def _parse_comparator_set(text: str, original: str) -> list[_Comparator]:
    tokens = text.split()
    if not tokens:
        raise ValueError(f"invalid range: {original!r}")

    comparators: list[_Comparator] = []
    index = 0
    while index < len(tokens):
        token = tokens[index]
        if token in _OPERATOR_SET:
            if index + 1 >= len(tokens):
                raise ValueError(f"invalid range: {original!r}")
            comparators.append(
                _parse_comparator(token, tokens[index + 1], original)
            )
            index += 2
        else:
            operator = "="
            version_text = token
            for candidate in _OPERATORS:
                if token.startswith(candidate):
                    operator = candidate
                    version_text = token[len(candidate) :]
                    break
            comparators.append(
                _parse_comparator(operator, version_text, original)
            )
            index += 1
    return comparators


def _matches(comparator: _Comparator, version: Version) -> bool:
    operator = comparator.operator
    bound = comparator.version

    if operator == "=":
        return compare(version, bound) == 0
    if operator == ">":
        return compare(version, bound) > 0
    if operator == ">=":
        return compare(version, bound) >= 0
    if operator == "<":
        return compare(version, bound) < 0
    if operator == "<=":
        return compare(version, bound) <= 0

    if compare(version, bound) < 0:
        return False

    if operator == "^":
        if bound.major != 0:
            upper = Version(bound.major + 1, 0, 0)
        elif bound.minor != 0:
            upper = Version(0, bound.minor + 1, 0)
        else:
            upper = Version(0, 0, bound.patch + 1)
    else:  # "~"
        upper = Version(bound.major, bound.minor + 1, 0)

    return compare(version, upper) < 0


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _coerce_version(version)
    if not isinstance(range_, str):
        raise ValueError(f"invalid range: {range_!r}")

    # Parse every set up front so that an invalid set anywhere in the range
    # raises, even when an earlier set would already have matched.
    sets = [
        _parse_comparator_set(part, range_) for part in range_.split("||")
    ]

    for comparators in sets:
        if candidate.prerelease and not any(
            comparator.version.prerelease
            and _same_release(comparator.version, candidate)
            for comparator in comparators
        ):
            continue
        if all(_matches(comparator, candidate) for comparator in comparators):
            return True
    return False

